namespace {
using Vec=std::array<double,3>;
Vec vec(const Json& p){return {p[0].get<double>(),p[1].get<double>(),p[2].get<double>()};}
Vec add(Vec a,Vec b){for(int i=0;i<3;i++)a[i]+=b[i];return a;}
Vec sub(Vec a,Vec b){for(int i=0;i<3;i++)a[i]-=b[i];return a;}
Vec mul(Vec a,double n){for(auto& v:a)v*=n;return a;}
double dot(Vec a,Vec b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
Vec cross(Vec a,Vec b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
Vec norm(Vec a){return mul(a,1/std::max(1e-12,std::sqrt(dot(a,a))));}
NSString* rs(const std::string& s){return [NSString stringWithUTF8String:s.c_str()]?:@"";}
NSColor* rc(double r,double g,double b){return [NSColor colorWithSRGBRed:r green:g blue:b alpha:1];}
NSStackView* rstack(BOOL vertical){auto s=[NSStackView stackViewWithViews:@[]];s.orientation=vertical?NSUserInterfaceLayoutOrientationVertical:NSUserInterfaceLayoutOrientationHorizontal;s.alignment=vertical?NSLayoutAttributeLeading:NSLayoutAttributeCenterY;s.spacing=7;return s;}
NSTextField* rlabel(NSString* value){auto f=[NSTextField labelWithString:value];f.font=[NSFont systemFontOfSize:11];return f;}
std::string editID(){return NSUUID.UUID.UUIDString.UTF8String;}
Json geometry(const Json& scene){return vj::roomPreviewSnapshot({{"room",{{"revision",0},{"scene",scene},{"history",{{"undo",Json::array()},{"redo",Json::array()}}}}}});}
const Json* selectedObject(const Json& scene,const std::string& selection){for(const auto* key:{"boxes","projectors"})for(const auto& o:scene[key])if(std::string(key==std::string("boxes")?"b":"p")+o["id"].get<std::string>()==selection)return &o;return nullptr;}
Vec rotateAxis(Vec axis,const Json& degrees){double x=degrees[0].get<double>()*M_PI/180,y=degrees[1].get<double>()*M_PI/180,z=degrees[2].get<double>()*M_PI/180;Vec a={axis[0],std::cos(x)*axis[1]-std::sin(x)*axis[2],std::sin(x)*axis[1]+std::cos(x)*axis[2]};Vec b={std::cos(y)*a[0]+std::sin(y)*a[2],a[1],-std::sin(y)*a[0]+std::cos(y)*a[2]};return {std::cos(z)*b[0]-std::sin(z)*b[1],std::sin(z)*b[0]+std::cos(z)*b[1],b[2]};}
Json worldRotation(const Json& initial,int axis,double angleDegrees){Vec n={0,0,0};n[axis]=1;double a=angleDegrees*M_PI/180,c=std::cos(a),s=std::sin(a);std::array<Vec,3> columns;for(int i=0;i<3;i++){Vec e={0,0,0};e[i]=1;auto v=rotateAxis(e,initial);columns[i]=add(add(mul(v,c),mul(cross(n,v),s)),mul(n,dot(n,v)*(1-c)));}double y=std::asin(std::clamp(-columns[0][2],-1.,1.)),x,z;if(std::abs(std::cos(y))>1e-6){x=std::atan2(columns[1][2],columns[2][2]);z=std::atan2(columns[0][1],columns[0][0]);}else{x=0;z=std::atan2(-columns[1][0],columns[1][1]);}return Json::array({x*180/M_PI,y*180/M_PI,z*180/M_PI});}
std::optional<double> rayTriangle(Vec origin,Vec direction,Vec a,Vec b,Vec c){auto e1=sub(b,a),e2=sub(c,a),p=cross(direction,e2);double determinant=dot(e1,p);if(std::abs(determinant)<1e-10)return {};auto t=sub(origin,a);double u=dot(t,p)/determinant;if(u<0||u>1)return {};auto q=cross(t,e1);double v=dot(direction,q)/determinant;if(v<0||u+v>1)return {};double distance=dot(e2,q)/determinant;return distance>.035?std::optional<double>(distance):std::nullopt;}
std::vector<Vec> clipNear(const std::vector<Vec>& polygon,Vec eye,Vec forward){std::vector<Vec> result;if(polygon.empty())return result;auto previous=polygon.back();double before=dot(sub(previous,eye),forward)-.035;for(auto current:polygon){double after=dot(sub(current,eye),forward)-.035;if((before<0)!=(after<0))result.push_back(add(previous,mul(sub(current,previous),before/(before-after))));if(after>=0)result.push_back(current);previous=current;before=after;}return result;}
struct Projection {NSPoint point;double depth;};
struct Face {std::vector<NSPoint> points;double depth,shade;bool front=true;std::string object;};
NSBezierPath* facePath(const Face& face){auto p=[NSBezierPath bezierPath];bool first=true;for(auto point:face.points){if(first)[p moveToPoint:point];else[p lineToPoint:point];first=false;}[p closePath];return p;}
