@end
@implementation VJRoomCanvas {Vec _target,_eye,_right,_up,_forward;double _yaw,_pitch,_distance,_focal;NSRect _viewport;NSPoint _shift,_start;BOOL _dragging,_pan,_orbit,_moved,_space;NSInteger _axis;Json _before;Vec _startTarget,_axisWorld;double _startYaw,_startPitch;std::vector<Face> _faces;std::array<NSPoint,3> _axisEnds;NSPoint _axisCenter;std::array<bool,3> _axisVisible;std::array<std::vector<NSPoint>,3> _rings;std::array<Face,3> _planes;NSInteger _planeAxis;Vec _gizmoCenter,_planeAnchor,_rotationStart;BOOL _rotationReady;}
