- (BOOL)isFlipped{return YES;}
- (BOOL)acceptsFirstResponder{return YES;}
- (BOOL)interacting{return _dragging;}
- (void)updateScene:(const Json&)value {scene=value;mesh=geometry(scene);[self setNeedsDisplay:YES];}
