- (void)frameSelection {if(!scene.is_object())return;if(const auto* object=selectedObject(scene,selection)){_target=vec((*object)[selection.starts_with("b")?"center":"position"]);_distance=selection.starts_with("b")?std::max({(*object)["size"][0].get<double>(),(*object)["size"][1].get<double>(),(*object)["size"][2].get<double>()})*3.2:3.2;_distance=std::clamp(_distance,.3,80.);}_yaw=M_PI/4;_pitch=.46;through=NO;[self setNeedsDisplay:YES];}
