- (void)mouseUp:(NSEvent*)event {(void)event;if(!_dragging)return;if((_axis>=0||_planeAxis>=0)&&_moved&&scene!=_before){if(self.editScene)self.editScene(scene,mode=="rotate"?"Rotate object":mode=="scale"?"Resize box":"Move object");}else if(!_moved&&!_pan&&!through&&_axis<0&&_planeAxis<0){std::string hit;double depth=INFINITY;auto ray=[self ray:_start];for(const auto& box:mesh["boxes"])for(const auto& face:box["faces"]){auto indices=face["vertices"];for(size_t i=1;i+1<indices.size();++i){auto distance=rayTriangle(_eye,ray,vec(box["vertices"][indices[0].get<size_t>()]),vec(box["vertices"][indices[i].get<size_t>()]),vec(box["vertices"][indices[i+1].get<size_t>()]));if(distance&&*distance<depth){depth=*distance;hit="b"+box["id"].get<std::string>();}}}for(const auto& p:mesh["projectors"]){auto at=[self project:vec(p["position"])];double distance=dot(sub(vec(p["position"]),_eye),ray);if(at&&distance<depth&&std::hypot(_start.x-at->point.x,_start.y-at->point.y)<15){hit="p"+p["id"].get<std::string>();depth=distance;}}if(!hit.empty()&&self.choose)self.choose(hit);}_dragging=NO;_axis=-1;_planeAxis=-1;[self setNeedsDisplay:YES];}
